DROP TABLE IF EXISTS site_content CASCADE;

CREATE TABLE site_content (
  section_id text PRIMARY KEY,
  data jsonb NOT NULL,
  updated_at timestamptz DEFAULT now()
);

ALTER TABLE site_content ENABLE ROW LEVEL SECURITY;
CREATE POLICY "anon_select_content" ON site_content FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "anon_insert_content" ON site_content FOR INSERT TO anon, authenticated WITH CHECK (true);
CREATE POLICY "anon_update_content" ON site_content FOR UPDATE TO anon, authenticated USING (true) WITH CHECK (true);
CREATE POLICY "anon_delete_content" ON site_content FOR DELETE TO anon, authenticated USING (true);

