INSERT INTO site_content (section_id, data) VALUES ('features', '{"badge":"Надёжный прокат","title":"Преимущества сервиса WAYS Rental","subtitle":"Мы делаем аренду съёмочной техники быстрой, прозрачной и безопасной для любого продакшна","items":[{"id":"1","icon":"shield","title":"Страховка включена","text":"Вся техника застрахована. Спокойствие на каждой съёмке."},{"id":"2","icon":"truck","title":"Доставка по городу","text":"Привезём оборудование прямо на площадку в удобное время."},{"id":"3","icon":"headphones","title":"Поддержка 24/7","text":"Поможем настроить и разобраться с любой единицей техники."}]}');
