INSERT INTO site_content (section_id, data) VALUES ('rental_rules', '{"title":"Правила аренды","subtitle":"Условия и порядок проката техники в WAYS Rental","rules":[{"num":"01","title":"Документы и оформление","desc":"Для оформления договора аренды требуется оригинал удостоверения личности или паспорта Республики Казахстан. Оформление занимает не более 5 минут."},{"num":"02","title":"Расчёт смены (24 часа)","desc":"Одна смена аренды длится до 24 часов с момента фактической передачи техники. Время возврата фиксируется в акте приёма-передачи."},{"num":"03","title":"Проверка и возврат","desc":"Техника проверяется при выдаче (сенсор, линзы, органы управления, батареи). Возврат производится в исправном и чистом виде со всеми аксессуарами."},{"num":"04","title":"Бронирование и оплата","desc":"Бронь подтверждается через WhatsApp с фиксацией дат и комплектации съёмки. Оплата принимается наличными, банковской картой или Kaspi QR."},{"num":"05","title":"Скидки на длительную аренду","desc":"От 3-х суток — скидка 15%. От 7 суток — скидка 25%. Для постоянных съёмочных команд действуют специальные партнёрские тарифы."}],"whatsappText":"Здравствуйте! Хочу уточнить правила аренды техники."}');
